# ====== 2) 로그에서 t,ch00,... 블록 추출 ======
blocks = []
current = None

for raw in io.StringIO(RAW_TEXT):
    line = raw.strip()
    if not line:
        continue

    # 새 데이터 블럭 헤더
    if line.startswith("t,ch00,"):
        if current:
            blocks.append(current)
        current = [line]
        continue

    # 데이터 블럭 내부
    if current is not None:
        # "숫자,숫자,..." 형태면 데이터라고 판단
        if re.match(r"^\d+,-?\d", line):
            current.append(line)
        else:
            # 합계, [Y], [AI_MODEL] 같은 로그 나오면 블럭 종료
            blocks.append(current)
            current = None

# 마지막 블럭 처리
if current:
    blocks.append(current)

if not blocks:
    raise RuntimeError("RAW_TEXT에서 't,ch00,...' 형태의 데이터 블럭을 찾지 못했습니다.")

print(f"발견된 데이터 블럭 개수: {len(blocks)}")

# ====== 3) ch00~ch29 → IMU1_ax~IMU5_gz 변환 함수 ======
def convert_block_to_df(block_lines, move_id, default_label=-1):
    csv_text = "\n".join(block_lines)
    df = pd.read_csv(io.StringIO(csv_text))

    # t → Timestep
    rename_map = {"t": "Timestep"}

    axes = ["ax", "ay", "az", "gx", "gy", "gz"]

    # 실제 ch 컬럼들
    ch_cols = [c for c in df.columns if c.startswith("ch")]
    ch_cols = sorted(ch_cols, key=lambda x: int(x[2:]))

    imu_count = len(ch_cols) // 6  # IMU 개수 (6축 기준)

    for imu_idx in range(imu_count):   # IMU1, IMU2, ...
        for axis_idx, axis_name in enumerate(axes):
            ch_name = f"ch{imu_idx*6 + axis_idx:02d}"   # ch00, ch01, ...
            imu_col = f"IMU{imu_idx+1}_{axis_name}"     # IMU1_ax, ...
            rename_map[ch_name] = imu_col

    df = df.rename(columns=rename_map)

    # move / label 추가
    df["move"] = move_id
    df["label"] = default_label

    # 컬럼 순서 정리 (Matlab 코드 호환)
    imu_cols = [c for c in df.columns
                if c.startswith("IMU") and any(ax in c for ax in axes)]
    imu_cols = sorted(imu_cols, key=lambda x: (int(x[3: x.index("_")]), x.split("_")[1]))

    df = df[["Timestep"] + imu_cols + ["move", "label"]]
    return df

# ====== 4) 모든 블럭 합쳐서 CSV 저장 ======
dfs = []
for i, block in enumerate(blocks, start=1):
    dfs.append(convert_block_to_df(block, move_id=i, default_label=-1))

df_all = pd.concat(dfs, ignore_index=True)

OUT_CSV = r"C:\Users\hjl99\Desktop\과제\캡디\imu_from_log.csv"  # 저장 경로만 수정
df_all.to_csv(OUT_CSV, index=False, float_format="%.6f")

print("CSV 저장 완료:", OUT_CSV)
print(df_all.head())
